class CatalogCache:
    def __init__(self, catalog):
        self.catalog = catalog
        self.entries = {}

    def get(self, id):
        cached = self.entries.get(id)
        current_version = self.catalog.versions.get(id, 0)
        if cached is not None and cached[0] == current_version:
            return None if cached[1] is None else cached[1].copy()
        value = self.catalog.read(id)
        self.entries[id] = (current_version, value)
        return None if value is None else value.copy()

