class Catalog:
    def __init__(self):
        self.products = {}
        self.versions = {}
        self.reads = 0

    def put(self, id, title):
        self.products[id] = {'id': id, 'title': title}
        self.versions[id] = self.versions.get(id, 0) + 1

    def delete(self, id):
        self.products.pop(id, None)
        self.versions[id] = self.versions.get(id, 0) + 1

    def read(self, id):
        self.reads += 1
        value = self.products.get(id)
        return None if value is None else value.copy()
